def affected(word) -> bool:
    # MUTANT always returns '', so the two differ exactly when ORIGINAL
    # finds a vowel at some index i in [1, len-2] whose neighbours are both consonants.
    v = 'aeiouAEIOU'
    return any(
        word[i] in v and word[i - 1] not in v and word[i + 1] not in v
        for i in range(1, len(word) - 1)
    )
